import React, { useState } from 'react';
import axios from 'axios';

function BookingForm() {
  const [userId, setUserId] = useState('');
  const [slotId, setSlotId] = useState('');  // still needed for booking
  const [vehicleNumber, setVehicleNumber] = useState('');
  const [startTime, setStartTime] = useState('');
  const [endTime, setEndTime] = useState('');
  const [message, setMessage] = useState('');

  // You can set slotId manually if needed, or input by user:
  // If you want to hardcode slotId, just set it directly.

  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
      const start = new Date(startTime);
      const end = new Date(endTime);
      const now = new Date();

      if (start >= end) {
        setMessage('Start time must be before end time');
        return;
      }

      if (start < now) {
        setMessage('Start time must be in the future');
        return;
      }

      if (!slotId) {
        setMessage('Slot ID is required');
        return;
      }

      if (!vehicleNumber) {
        setMessage('Vehicle number is required');
        return;
      }

      const res = await axios.post(`http://localhost:8080/api/bookings?userId=${userId}&parkingSlotId=${slotId}`, {
        vehicleNumber,
        startTime,
        endTime
      });

      setMessage('Booking successful!');
    } catch (err) {
      const msg =
        typeof err?.response?.data === 'string'
          ? err.response.data
          : err?.response?.data?.message || 'Booking failed!';
      setMessage(msg);
    }
  };

  return (
    <div>
      <h2>Book a Parking Slot</h2>
      <form onSubmit={handleSubmit}>
        <div>
          <label>User ID:</label>
          <input
            type="text"
            value={userId}
            onChange={(e) => setUserId(e.target.value)}
            required
          />
        </div>
        <div>
          <label>Parking Slot ID:</label>
          <input
            type="text"
            value={slotId}
            onChange={(e) => setSlotId(e.target.value)}
            required
          />
        </div>
        <div>
          <label>Vehicle Number:</label>
          <input
            type="text"
            value={vehicleNumber}
            onChange={(e) => setVehicleNumber(e.target.value)}
            required
          />
        </div>
        <div>
          <label>Start Time:</label>
          <input
            type="datetime-local"
            value={startTime}
            onChange={(e) => setStartTime(e.target.value)}
            required
          />
        </div>
        <div>
          <label>End Time:</label>
          <input
            type="datetime-local"
            value={endTime}
            onChange={(e) => setEndTime(e.target.value)}
            required
          />
        </div>
        <button type="submit">Book</button>
      </form>
      {message && <p>{message}</p>}
    </div>
  );
}

export default BookingForm;
